<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){try{db()->prepare('INSERT INTO exams(exam_name,semester,academic_session,exam_type) VALUES(?,?,?,?)')->execute([trim($_POST['exam_name']),(int)$_POST['semester'],trim($_POST['academic_session']),trim($_POST['exam_type'])]);audit('Created exam');flash('success','Examination created.');}catch(Throwable $e){flash('danger','Unable to create examination.');}redirect('exams.php');}
$rows=db()->query('SELECT * FROM exams ORDER BY exam_id DESC')->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="row g-3"><div class="col-md-4"><div class="card"><div class="card-header">Create examination</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-2"><label class="form-label">Exam name</label><input class="form-control" name="exam_name" required></div><div class="mb-2"><label class="form-label">Exam type</label><select class="form-select" name="exam_type"><option>Midterm</option><option>Final</option><option>Quiz</option><option>Assignment</option></select></div><div class="mb-2"><label class="form-label">Semester</label><input class="form-control" type="number" name="semester" min="1" max="12" required></div><div class="mb-3"><label class="form-label">Academic session</label><input class="form-control" name="academic_session" placeholder="2026-2027" required></div><button class="btn btn-primary">Create exam</button></form></div></div></div><div class="col-md-8"><div class="card"><div class="card-header">Examination records</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Exam</th><th>Type</th><th>Semester</th><th>Session</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['exam_name'])?></td><td><?=e($r['exam_type'])?></td><td><?=e((string)$r['semester'])?></td><td><?=e($r['academic_session'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
